function a(t){return t.normalize("NFKD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}function s(t){return a(t).replace(/ /g,"")}function h(t){let r=t.map(n=>n.classification).filter(n=>!!n);return[...new Set(r)].sort()}function m(t,{query:r="",classification:n=""}){let e=a(r);return t.filter(i=>(!n||i.classification===n)&&(!e||a(i.name).includes(e)))}function g(t,{query:r="",strainSlug:n=""}){let e=a(r),i=s(r),f=[];for(let c of t){if(n&&c.slug!==n)continue;let o=!e||a(c.name).includes(e);for(let u of c.batches){let l=s(u.id),d=!!i&&l===i;(o||i&&l.includes(i))&&f.push({strain:c,batch:u,exactBatch:d})}}return f.sort((c,o)=>Number(o.exactBatch)-Number(c.exactBatch))}function p(t,r){if(!r)return;let n=s(r);return t.batches.find(e=>s(e.id)===n)}export{h as a,m as b,g as c,p as d};
